	 */
	private static final Map<Integer, String> ATTR_TYPE_NAMES = new LinkedHashMap<>();

	static {
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_REFERENCE, "reference");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_STRING, "string");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_INTEGER, "integer");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_BOOLEAN, "boolean");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_COLOR, "color");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_FLOAT, "float");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_DIMENSION, "dimension");
		ATTR_TYPE_NAMES.put(ValuesParser.ATTR_TYPE_FRACTION, "fraction");
	}

	public static String getAttrTypeAsString(int type) {
		StringBuilder sb = new StringBuilder();
		ATTR_TYPE_NAMES.forEach((flag, name) -> {
			if ((type & flag) != 0) {
				sb.append('|').append(name);
			}
		});
		if (sb.length() == 0) {
			return null;
		}
		return sb.substring(1);
	}
}

